const deploymentList = document.querySelector("#deployment-list");
const year = document.querySelector("#year");

const deploymentChecklist = [
    "Choose a static host such as Vercel or Netlify.",
    "Add your production domain and DNS records.",
    "Verify that links, images, and metadata still work after deployment.",
];

for (const item of deploymentChecklist) {
    const li = document.createElement("li");
    li.textContent = item;
    deploymentList?.appendChild(li);
}

if (year) {
    year.textContent = `Updated ${new Date().getFullYear()}`;
}

:root {
    color-scheme: light;
    font-family: "Trebuchet MS", sans-serif;
    background: #f7f4ee;
    color: #1e1c19;
}

body {
    margin: 0;
    min-height: 100vh;
    background:
        radial-gradient(circle at top left, #ffe4b8, transparent 24rem),
        linear-gradient(180deg, #f7f4ee 0%, #ffffff 100%);
}

.hero,
.section,
.footer {
    width: min(70rem, calc(100vw - 2rem));
    margin: 0 auto;
}

.hero {
    padding: 5rem 0 2rem;
}

.eyebrow {
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-size: 0.8rem;
}

.lead {
    max-width: 36rem;
    line-height: 1.6;
}

.section {
    padding: 1.5rem 0;
}

.grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
    gap: 1rem;
}

.card {
    background: rgba(255, 255, 255, 0.9);
    border: 1px solid rgba(30, 28, 25, 0.08);
    border-radius: 1rem;
    padding: 1rem;
}

.footer {
    display: flex;
    justify-content: space-between;
    gap: 1rem;
    padding: 2rem 0 3rem;
    font-size: 0.95rem;
}

@media (max-width: 640px) {
    .footer {
        flex-direction: column;
    }
}

WDF1-Portfolio-Custom-Domain/basics/solu.content:
const deploymentList = document.querySelector("#deployment-list");
const domainStatus = document.querySelector("#domain-status");
const year = document.querySelector("#year");

const deploymentChecklist = [
    "Publish the built site to a static host.",
    "Connect the custom domain and verify DNS propagation.",
    "Confirm HTTPS, metadata, and responsive layout in production.",
    "Document rollback steps before changing DNS.",
];

for (const item of deploymentChecklist) {
    const li = document.createElement("li");
    li.textContent = item;
    deploymentList?.appendChild(li);
}

if (domainStatus) {
    domainStatus.textContent =
        "Point your domain to the static host, wait for HTTPS issuance, then run a final content and link audit.";
}

if (year) {
    year.textContent = `Updated ${new Date().getFullYear()}`;
}

:root {
    color-scheme: light;
    font-family: Georgia, "Times New Roman", serif;
    background: #f4efe8;
    color: #1f1712;
}

body {
    margin: 0;
    min-height: 100vh;
    background:
        radial-gradient(
            circle at 15% 10%,
            rgba(227, 185, 115, 0.35),
            transparent 22rem
        ),
        linear-gradient(180deg, #f4efe8 0%, #fffefb 100%);
}

.hero,
.section,
.footer {
    width: min(72rem, calc(100vw - 2rem));
    margin: 0 auto;
}

.hero {
    padding: 5rem 0 2.5rem;
}

.eyebrow {
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-size: 0.78rem;
}

.lead {
    max-width: 42rem;
    line-height: 1.65;
}

.cta {
    display: inline-block;
    margin-top: 1rem;
    padding: 0.8rem 1.15rem;
    border-radius: 999px;
    text-decoration: none;
    color: white;
    background: #9a4d1b;
}

.section {
    padding: 1.5rem 0;
}

.grid,
.stack {
    display: grid;
    gap: 1rem;
}

.grid {
    grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
}

.stack {
    grid-template-columns: 2fr 1fr;
}

.card,
.domain-box {
    background: rgba(255, 255, 255, 0.88);
    border: 1px solid rgba(31, 23, 18, 0.08);
    border-radius: 1.1rem;
    padding: 1rem;
}

.footer {
    display: flex;
    justify-content: space-between;
    gap: 1rem;
    padding: 2rem 0 3rem;
}

@media (max-width: 720px) {
    .stack,
    .footer {
        grid-template-columns: 1fr;
        flex-direction: column;
    }
}
